// Issue #65: the browser engine against the Python scorer, case by case.
// Expected values come from public/data/test-fixtures/terrain-scoring.json, generated by
// pipeline/scoring_fixtures.py from pipeline/scan.py (similarity, terrain_match) and config/weights.yaml
// (#64, docs/SCORING-FIXTURES.md). Nothing here is a hand-written score. The fixture is imported by this
// test only; the app never fetches it.
import { describe, expect, it } from 'vitest'
import fixture from '../../public/data/test-fixtures/terrain-scoring.json'
import type { ParamKey, Site, Target, Value, Weights, WindowKey } from '../types'
import { PARAM_KEYS, WINDOW_KEYS } from '../types'
import { compareScores, defaultWeights, scoreSite, similarity, terrainMatch } from './scoring'
import { config } from './fixture'

type Raw = number | null | { non_finite: string }
interface Expected {
  completeness: number; included_weight: number; total_weight: number; weighted_sum: number
  missing: string[]; per_parameter_similarity: Record<string, number | null>; terrain_match: number | null
}
interface Case {
  id: string; description: string; target_body: string; window_km?: number
  target_values: Record<string, Raw>; weights: Record<string, number>
  sites: { id: string; values: Record<string, Raw> }[]
  expected: { ranked_site_ids: string[]; sites: Record<string, Expected> }
}
const cases = fixture.cases as unknown as Case[]

/** The fixture's JSON-safe markers for non-finite inputs, decoded as docs/SCORING-FIXTURES.md says. */
const NON_FINITE: Record<string, number> = { 'not-a-number': NaN, 'positive-infinite': Infinity, 'negative-infinite': -Infinity }
function decode(x: Raw): number | null {
  if (x === null || typeof x === 'number') return x
  const v = NON_FINITE[x.non_finite]
  if (v === undefined) throw new Error(`unknown non_finite marker ${x.non_finite}`)
  return v
}
const values = (raw: Record<string, Raw>): Record<ParamKey, Value> =>
  Object.fromEntries(PARAM_KEYS.map(k => {
    const v = decode(raw[k])
    return [k, { value: v, tier: 'estimated', source: 'fixture' }]
  })) as Record<ParamKey, Value>
const plain = (raw: Record<string, Raw>) => Object.fromEntries(PARAM_KEYS.map(k => [k, decode(raw[k])])) as Record<ParamKey, number | null>

// Tolerance: inputs and ranges are small exact decimals; each score is at most 3 products and 2 sums
// plus one division, so the two languages can differ only by a few ulps of values ≤ 3. 1e-12 is far
// above that and far below the 0.01 the app displays. Statuses, missing keys, ids and order are exact.
const TOL = 1e-12
const close = (a: number | null, b: number | null) => (a === null || b === null ? a === b : Math.abs(a - b) <= TOL)

describe('fixture provenance', () => {
  it('was generated from the same parameters, ranges, default weights and windows the app uses', () => {
    const p = fixture.producer
    expect(p.scorer).toContain('pipeline/scan.py')
    expect(p.parameter_order).toEqual(PARAM_KEYS)
    for (const k of PARAM_KEYS) {
      const fx = (p.configured_params as Record<string, { range: number; weight: number }>)[k]
      expect(fx.range, k).toBe(config.params[k].range)
      expect(fx.weight, k).toBe(defaultWeights(config)[k])
    }
    expect(p.configured_window_sizes_km).toEqual(config.window_sizes_km)
    expect(cases.length).toBeGreaterThan(0)
  })
})

describe.each(cases.map(c => [c.id, c] as const))('Python parity: %s', (_id, c) => {
  const weights = Object.fromEntries(PARAM_KEYS.map(k => [k, c.weights[k]])) as Weights
  const target = values(c.target_values)

  it('per-parameter similarity, Terrain Match, completeness and missing keys', () => {
    for (const s of c.sites) {
      const exp = c.expected.sites[s.id]
      const got = terrainMatch(values(s.values), target, config, weights)
      for (const p of got.perParam) {
        expect(close(p.similarity, exp.per_parameter_similarity[p.key]), `${s.id} ${p.key}: ${p.similarity} vs ${exp.per_parameter_similarity[p.key]}`).toBe(true)
        expect(close(p.similarity, similarity(decode(s.values[p.key]), decode(c.target_values[p.key]), config.params[p.key].range))).toBe(true)
      }
      expect(close(got.terrainMatch, exp.terrain_match), `${s.id} terrain match: ${got.terrainMatch} vs ${exp.terrain_match}`).toBe(true)
      expect(close(got.completeness, exp.completeness), `${s.id} completeness: ${got.completeness} vs ${exp.completeness}`).toBe(true)
      expect([...got.missing].sort(), `${s.id} missing`).toEqual([...exp.missing].sort())
    }
  })

  it('ranks in the same order: score descending, unscored last, ties by site id', () => {
    const scored = c.sites.map(s => ({ siteId: s.id, terrainMatch: terrainMatch(values(s.values), target, config, weights).terrainMatch }))
    expect([...scored].sort(compareScores).map(s => s.siteId)).toEqual(c.expected.ranked_site_ids)
  })

  if (c.window_km !== undefined) {
    it(`scores the ${c.window_km} km window descriptors the same way`, () => {
      const key = String(c.window_km) as WindowKey
      expect(WINDOW_KEYS).toContain(key)
      const t = { id: 't', name: 't', body: c.target_body, params: target, windows: { [key]: plain(c.target_values) } } as unknown as Target
      for (const s of c.sites) {
        const site = { id: s.id, params: values(s.values), windows: { [key]: plain(s.values) }, conditions: { low_sun_share: { value: null, tier: 'missing', source: null } } } as unknown as Site
        const got = scoreSite(site, t, config, weights).windowSensitivity[key]
        expect(close(got, c.expected.sites[s.id].terrain_match), `${s.id} window ${key}`).toBe(true)
      }
    })
  }
})
